import {probePlacementAt as calibratedProbe,GEOMETRY_VERSION} from './thermal-apparatus.js?v=87';
import {initialPositions,probePlacementAt} from './apparatus-registry.js?v=84';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const en=locale=>/^en/i.test(locale||'');
export const SESSION_SCHEMA='lab.session.v3';
export function newSession(activity){return {schemaVersion:SESSION_SCHEMA,modelVersion:'thermal.nodes.v1',catalogId:'calorimetry',activity,sessionId:globalThis.crypto?.randomUUID?.()||'session-'+Date.now().toString(36),createdAt:new Date().toISOString(),mode:'guided',trials:[],legacySessions:[],apparatusState:{positions:initialPositions(),cupAngleRad:0}};}
export function newTrial(session,activity,conditionsSI){const trial={trialId:'trial-'+(session.trials.length+1),activity,hypothesis:'',conditionsSI:structuredClone(conditionsSI),events:[],readings:[],trace:[],analysis:'',conclusion:''};if(session.trials.length>=20)throw new RangeError('20 trials maximum; export this session first');session.trials.push(trial);return trial;}
export const currentTrial=session=>session.trials.at(-1);
function inspect(value,depth=0){if(depth>18)throw new RangeError('Session nesting too deep');if(typeof value==='number'&&!Number.isFinite(value))throw new TypeError('Nonfinite number');if(typeof value==='string'&&value.length>20000)throw new RangeError('Text too long');if(value&&typeof value==='object'){if(Array.isArray(value)&&value.length>10000)throw new RangeError('Collection too long');for(const [k,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))throw new TypeError('Unsafe object key');inspect(v,depth+1);}}}
export function parseSession(text,{activity,validateState}={}){
 if(typeof text!=='string'||text.length>1500000)throw new RangeError('Session file exceeds 1.5 MB');const input=JSON.parse(text);inspect(input);
 if(input?.schema==='thpt.session.v1'||input?.schemaVersion==='thpt.session.v1'){
  if((input.id||input.catalogId)!=='calorimetry'||!Array.isArray(input.rows)||input.rows.length>500)throw new TypeError('Unsupported classic session');
  const migrated=newSession(activity||'ice');migrated.legacySessions=[structuredClone(input)];return {session:migrated,legacy:true};
 }
 if(input?.schemaVersion!==SESSION_SCHEMA||input.modelVersion!=='thermal.nodes.v1'||input.catalogId!=='calorimetry'||!['ice','solid'].includes(input.activity)||activity&&input.activity!==activity)throw new TypeError('Wrong session schema, activity or model version');
 if(typeof input.sessionId!=='string'||input.sessionId.length>100||!['explore','guided','assessment'].includes(input.mode)||!Array.isArray(input.trials)||input.trials.length<1||input.trials.length>20)throw new TypeError('Invalid session metadata');
 const plain=value=>!!value&&typeof value==='object'&&!Array.isArray(value);
 if(!plain(input.apparatusState)||!plain(input.apparatusState.positions)||!Number.isFinite(input.apparatusState.cupAngleRad)||input.apparatusState.cupAngleRad<0||input.apparatusState.cupAngleRad>100*Math.PI/180+1e-8)throw new TypeError('Invalid apparatus state');
 for(const [id,p]of Object.entries(input.apparatusState.positions))if(!['calorimeter','cup','ice','probe','stirrer','tongs','solid','scale','bath'].includes(id)||!plain(p)||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>800||p.y<0||p.y>480)throw new TypeError('Invalid apparatus position');
 const camera=input.apparatusState.camera;if(camera!==undefined&&camera!==null&&(!plain(camera)||!['x','y','width','height'].every(k=>Number.isFinite(camera[k]))||camera.width<400-1e-6||camera.width>800/.75+1e-6||Math.abs(camera.height-camera.width*.6)>1e-5||Math.abs(camera.x)>1600||Math.abs(camera.y)>960))throw new TypeError('Invalid camera');
 if(input.apparatusState.geometryVersion!==undefined&&input.apparatusState.geometryVersion!==GEOMETRY_VERSION)throw new TypeError('Unsupported apparatus geometry');if(input.apparatusState.icePieceMassKg!==undefined&&(!Number.isFinite(input.apparatusState.icePieceMassKg)||input.apparatusState.icePieceMassKg<.001||input.apparatusState.icePieceMassKg>.1))throw new TypeError('Invalid ice portion');if(input.apparatusState.geometryBackupId!==undefined&&(!Number.isSafeInteger(input.apparatusState.geometryBackupId)||input.apparatusState.geometryBackupId<=0))throw new TypeError('Invalid geometry backup');
 if(input.drafts!==undefined){if(!plain(input.drafts))throw new TypeError('Invalid drafts');for(const [k,v]of Object.entries(input.drafts)){if(k==='temperature'){if(typeof v!=='string')throw new TypeError('Invalid temperature draft');}else if(!['calculation','config','masses'].includes(k)||!plain(v)||Object.values(v).some(x=>typeof x!=='string'))throw new TypeError('Invalid form drafts');}}
 if(input.legacySessions!==undefined&&(!Array.isArray(input.legacySessions)||input.legacySessions.length>5||input.legacySessions.some(s=>!plain(s)||(s.schema||s.schemaVersion)!=='thpt.session.v1'||s.id!=='calorimetry'||!Array.isArray(s.rows)||s.rows.length>500)))throw new TypeError('Invalid classic session collection');
 for(const trial of input.trials){
  if(typeof trial.trialId!=='string'||trial.trialId.length>100||!plain(trial.conditionsSI)||['hypothesis','analysis','conclusion'].some(k=>typeof trial[k]!=='string'))throw new TypeError('Invalid trial text or conditions');
  for(const row of Array.isArray(trial.readings)?trial.readings:[]){
   if(!plain(row)||row.method!=='manual'||row.instrumentId!=='thermometer'||!plain(row.conditionsSI)||row.excludedReason!==undefined&&typeof row.excludedReason!=='string')throw new TypeError('Invalid reading metadata');
   if(row.observation!==undefined&&(!plain(row.observation)||row.observation.status!==undefined&&typeof row.observation.status!=='string'||row.observation.probePlacement!==undefined&&!['air','wall','water','bath','solid'].includes(row.observation.probePlacement)))throw new TypeError('Invalid reading placement');
  }
  for(const row of Array.isArray(trial.trace)?trial.trace:[])if(!plain(row)||!Number.isFinite(row.simTimeS)||row.simTimeS<0||!['ice-and-water','liquid'].includes(row.phase)||typeof row.valid!=='boolean'||row.displayTemperatureC!==null&&!Number.isFinite(row.displayTemperatureC))throw new TypeError('Invalid trace metadata');
 }
 for(const trial of input.trials)for(const row of Array.isArray(trial.readings)?trial.readings:[])if(row.studentMassesKg!==undefined&&(!plain(row.studentMassesKg)||Object.entries(row.studentMassesKg).some(([k,v])=>!['water','sample'].includes(k)||typeof v!=='number'||!Number.isFinite(v)||v<0||v>2)))throw new TypeError('Invalid manual mass entry');
 for(const trial of input.trials){if(trial.activity!==input.activity||!Array.isArray(trial.readings)||trial.readings.length>500||!Array.isArray(trial.events)||trial.events.length>5000||!Array.isArray(trial.trace)||trial.trace.length>10000)throw new TypeError('Invalid trial collections');for(const row of trial.readings)if(!Number.isFinite(row.studentValueC)||Math.abs(row.studentValue-row.studentValueC-273.15)>1e-7||row.measuredValue!==null&&!Number.isFinite(row.measuredValue)||!Number.isFinite(row.simTimeS)||row.simTimeS<0||row.unit!=='K'||!Number.isFinite(row.studentValue)||row.studentValue<0||typeof row.valid!=='boolean')throw new TypeError('Invalid manual reading');for(const event of trial.events)if(event.schemaVersion!==1||event.labId!=='calorimetry'||!Number.isFinite(event.simTimeS)||typeof event.actionType!=='string'||typeof event.accepted!=='boolean')throw new TypeError('Invalid event');}
 const checked=validateState?validateState(input.physicalState):true;
 if(!input.physicalState||input.physicalState.activity!==input.activity||!(checked===true||checked?.valid===true))throw new TypeError('Invalid physical state');
 if(Object.keys(initialPositions()).some(id=>!plain(input.apparatusState.positions[id]))||(input.apparatusState.geometryVersion===GEOMETRY_VERSION?calibratedProbe:probePlacementAt)(input.apparatusState.positions.probe,input.physicalState,input.apparatusState.positions)!==input.physicalState.probe.placement)throw new TypeError('Probe placement contradicts apparatus geometry');
 return {session:structuredClone(input),legacy:false};
}
export function serializeSession(session){inspect(session);return JSON.stringify(session,null,2);}
export function exportCSV(session){
 const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=[['trial_id','activity','source','sim_time_s','instrument','student_temperature_K','display_temperature_C','instrument_temperature_K','valid','representative','method','water_mass_kg','ice_mass_kg','phase','energy_in_J','energy_out_J','energy_residual_J','mass_residual_kg','excluded_reason','conditions_SI','student_water_mass_kg','student_sample_mass_kg']];
 for(const trial of session.trials){for(const r of trial.readings)rows.push([trial.trialId,trial.activity,'student',r.simTimeS,r.instrumentId,r.studentValue,r.studentValueC,r.measuredValue,r.valid,r.representative,r.method,r.observation?.waterMassKg,r.observation?.iceMassKg,'','','',r.observation?.energyResidualJ,r.observation?.massResidualKg,r.excludedReason||'',JSON.stringify(r.conditionsSI),r.studentMassesKg?.water??'',r.studentMassesKg?.sample??'']);for(const r of trial.trace)rows.push([trial.trialId,trial.activity,'instrument-trace',r.simTimeS,'thermometer','',r.displayTemperatureC,Number.isFinite(r.displayTemperatureC)?r.displayTemperatureC+273.15:'',r.valid,r.representative,'automatic',r.waterMassKg,r.iceMassKg,r.phase,r.energyInJ,r.energyOutJ,r.energyResidualJ,r.massResidualKg,'',JSON.stringify(r.conditionsSI||{}),'','']);}
 return '\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n');
}
export function renderNotebook(session,locale){const e=en(locale),t=currentTrial(session)||{};return `<div class="l3-notebook-heading"><h2>${e?'Experiment notebook':'Sổ tay thực nghiệm'}</h2><div class="l3-data-actions"><button data-l3-action="export-csv">CSV</button><button data-l3-action="export-json">JSON</button><button data-l3-action="import">${e?'Import session':'Nhập phiên'}</button><input id="l3Import" type="file" accept="application/json,.json" hidden></div></div><div class="l3-setup"><label>${e?'Source water / kg':'Nước trong cốc / kg'}<input data-l3-config="waterMassKg" type="number" min=".01" max="1" step=".01"></label><label>${e?'Water temperature / °C':'Nhiệt độ nước / °C'}<input data-l3-config="waterTempC" type="number" min="1" max="95" step="1"></label><label>${session.activity==='ice'?(e?'Ice available / kg':'Đá trong khay / kg'):(e?'Solid mass / kg':'Khối lượng vật rắn / kg')}<input data-l3-config="sampleMassKg" type="number" min=".001" max=".5" step=".001"></label><label>${e?'Calorimeter heat capacity / J·K⁻¹':'Nhiệt dung bình / J·K⁻¹'}<input data-l3-config="calorimeterHeatCapacityJPerK" type="number" min="0" max="1000" step="10"></label><button data-l3-action="new-trial">${e?'Apply to new trial':'Áp dụng cho lượt mới'}</button></div><div class="l3-writing"><label>${e?'Prediction before acting':'Dự đoán trước khi thao tác'}<textarea data-l3-note="hypothesis" maxlength="4000">${esc(t.hypothesis)}</textarea></label><label>${e?'Observed thermometer / °C':'Số chỉ em đọc trên nhiệt kế / °C'}<input id="l3StudentTemperature" type="number" min="-50" max="150" step=".1" inputmode="decimal" autocomplete="off"><small>${e?'Your entry is kept even if misread.':'Giữ nguyên số em nhập, kể cả khi đọc nhầm.'}</small></label><button data-l3-action="record">${e?'Record this reading':'Ghi số đo này'}</button></div><p id="l3TrialSummary" role="status"></p><div class="l3-data-scroll" role="region" tabindex="0" aria-label="${e?'Experiment readings':'Số đo thực nghiệm'}"><table><thead><tr>${(e?['Trial','t / s','Entry / °C','Instrument / °C','Placement','Conditions']:['Lượt','t / s','Em ghi / °C','Dụng cụ / °C','Vị trí đo','Điều kiện']).map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody id="l3Rows"></tbody></table></div><div id="l3Graph" class="l3-graph" aria-label="${e?'Recorded temperature versus simulation time':'Nhiệt độ tự ghi theo thời gian mô phỏng'}"></div><div class="l3-writing"><label>${e?'Analysis from your data':'Phân tích từ số liệu của em'}<textarea data-l3-note="analysis" maxlength="6000">${esc(t.analysis)}</textarea></label><label>${e?'Conclusion and limitations':'Kết luận và giới hạn'}<textarea data-l3-note="conclusion" maxlength="6000">${esc(t.conclusion)}</textarea></label></div>${session.activity==='solid'?`<details class="l3-calculation"><summary>${e?'Calculate specific heat from your readings':'Tính nhiệt dung riêng từ số đo của em'}</summary><p>${e?'Enter measured masses and temperatures. The tool does not supply equilibrium readings.':'Nhập khối lượng và nhiệt độ đã đo. Công cụ không điền sẵn nhiệt độ cân bằng.'}</p><div class="l3-setup">${[['mw',e?'Water mass / kg':'m nước / kg'],['ccal',e?'Calorimeter capacity / J·K⁻¹':'C bình / J·K⁻¹'],['ms',e?'Solid mass / kg':'m vật / kg'],['tw',e?'Initial water T / °C':'T nước đầu / °C'],['ts',e?'Initial solid T / °C':'T vật đầu / °C'],['tf',e?'Final T / °C':'T cuối / °C']].map(([id,label])=>`<label>${label}<input data-l3-calc="${id}" type="number" step="any"></label>`).join('')}<button data-l3-action="calculate">${e?'Calculate':'Tính'}</button></div><output id="l3Calculated"></output></details>`:''}<details id="l3Legacy"><summary>${e?'Preserved classic sessions':'Phiên mô hình cũ được giữ lại'}</summary><p>${e?'Classic two-water measurements are preserved separately; they are not reclassified as ice or solid experiments.':'Số đo trộn hai lượng nước được giữ riêng, không đổi nhãn thành thí nghiệm nước–đá hoặc vật rắn.'}</p><div id="l3LegacyRows"></div></details>`;}
export function refreshNotebook(host,session,locale){const e=en(locale),nf=n=>Number.isFinite(n)?n.toLocaleString(e?'en-US':'vi-VN',{maximumFractionDigits:2}):'—';let count=0;const rows=[];for(const trial of session.trials)for(const [index,r] of trial.readings.entries()){count++;const placement=r.observation?.probePlacement;const placementLabel=({water:e?'In water':'Trong nước',bath:e?'In heating bath':'Trong bể',solid:e?'On solid':'Trên vật rắn',wall:e?'On wall':'Trên thành bình',air:e?'Not immersed':'Chưa nhúng'})[placement]||(e?'Unknown placement':'Chưa rõ vị trí');rows.push(`<tr><td>${esc(trial.trialId)}</td><td>${nf(r.simTimeS)}</td><td>${nf(r.studentValueC)}</td><td>${nf(r.measuredValue===null?null:r.measuredValue-273.15)}</td><td>${placementLabel}${r.valid?'':' ⚠'}${r.representative===false?(e?' · local/nonuniform':' · cục bộ/chưa đồng đều'):''}</td><td>${nf(r.conditionsSI?.waterMassKg)} kg · ${nf(r.conditionsSI?.iceMassKg??r.conditionsSI?.solidMassKg)} kg<br><button data-l3-exclude="${session.trials.indexOf(trial)}:${index}">${r.excludedReason?(e?'Restore point':'Dùng lại điểm'):(e?'Exclude with reason':'Loại điểm có lí do')}</button>${r.excludedReason?'<small>'+esc(r.excludedReason)+'</small>':''}</td></tr>`);}host.querySelector('#l3Rows').innerHTML=rows.join('');host.querySelector('#l3TrialSummary').textContent=e?`${session.trials.length} trials · ${count} manual readings`:`${session.trials.length} lượt · ${count} số đo tự ghi`;const trial=currentTrial(session),points=trial?.readings.filter(r=>r.valid&&!r.excludedReason)||[],graph=host.querySelector('#l3Graph');if(!points.length){graph.textContent=e?'Enter readings to plot your temperature trace.':'Nhập số đo để vẽ đường nhiệt độ của em.';}else{const xs=points.map(p=>p.simTimeS),ys=points.map(p=>p.studentValueC),x0=Math.min(0,...xs),x1=Math.max(x0+1,...xs),y0=Math.min(...ys)-1,y1=Math.max(...ys)+1,coords=points.map(p=>`${40+520*(p.simTimeS-x0)/(x1-x0)},${180-150*(p.studentValueC-y0)/(y1-y0)}`);graph.innerHTML=`<p>T (°C) · t (s) · ${esc(trial.trialId)}</p><svg viewBox="0 0 600 220" role="img" aria-label="${e?'Student-recorded temperature':'Nhiệt độ do người học ghi'}"><path d="M40 20V180H570" fill="none" stroke="currentColor"/><polyline points="${coords.join(' ')}" fill="none" stroke="#2879ad" stroke-width="2"/>${coords.map((c,i)=>{const [x,y]=c.split(',');return `<circle cx="${x}" cy="${y}" r="4" fill="currentColor"><title>${nf(xs[i])} s: ${nf(ys[i])} °C</title></circle>`;}).join('')}<text x="40" y="208">${nf(x0)} s</text><text x="520" y="208">${nf(x1)} s</text><text x="45" y="30">${nf(y1)} °C</text><text x="45" y="170">${nf(y0)} °C</text></svg>`;}host.querySelector('#l3LegacyRows').innerHTML=(session.legacySessions||[]).map((legacy,i)=>`<p>${esc(legacy.id)} · ${legacy.rows?.length||0} ${e?'classic rows':'dòng cũ'}</p><pre>${esc(JSON.stringify(legacy.rows,null,2))}</pre><button data-l3-legacy="${i}">${e?'Export original session':'Xuất lại phiên gốc'}</button>`).join('');}
